<!DOCTYPE html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}" class="scroll-smooth">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="description" content="{{ __('KI-gestützte Aktienanalyse mit klaren Signalen, Risiko-Kennzahlen und Strategietests.') }}">
    <title>{{ __('AktienKI – Signale früher erkennen') }}</title>
    <link rel="icon" href="{{ asset('brand/generated/bull-icon.png') }}" type="image/png">
    <script>
        (() => {
            const welcomeVersionKey = 'aktienki-welcome-theme-version';
            const welcomeVersion = 'dark-default-v1';
            if (localStorage.getItem(welcomeVersionKey) !== welcomeVersion) {
                localStorage.setItem('aktienki-theme', 'dark');
                localStorage.setItem('aktienki-theme-version', 'light-default-v1');
                localStorage.setItem(welcomeVersionKey, welcomeVersion);
            }
            const dark = localStorage.getItem('aktienki-theme') !== 'light';
            document.documentElement.dataset.theme = dark ? 'dark' : 'light';
            document.documentElement.style.colorScheme = dark ? 'dark' : 'light';
        })();
    </script>
    @vite(['resources/css/app.css', 'resources/js/app.js'])
    <style>
        :root{--bg:#031015;--panel:rgba(7,30,38,.82);--line:rgba(117,242,255,.12);--cyan:#52f1ff;--cyan2:#18cfe3;--text:#f2fdff;--muted:#89a8af;--green:#4df2a8;--red:#ff7b92;--shadow:0 25px 80px rgba(0,0,0,.45)}
