        .market-panel{display:grid;grid-template-columns:minmax(330px,34%) 1fr}.market-top{display:block;border-bottom:0;border-right:1px solid rgba(82,241,255,.2);padding:23px 20px}.market-top .donuts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:20px 0 15px;padding:15px 8px;border:1px solid rgba(82,241,255,.14);border-radius:15px;background:rgba(3,18,28,.45)}.market-top .donut{width:78px;height:78px;margin:auto}.market-top .donut-number{font-size:14px}.assessment-trend{padding:14px;border:1px solid rgba(82,241,255,.15);border-radius:13px;background:rgba(3,18,28,.4)}.assessment-trend small{display:block;color:#6f929a;font-size:8px;letter-spacing:.08em}.assessment-trend strong{display:block;color:var(--cyan);font-size:18px;margin-top:7px}.horizon-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:10px}.horizon{padding:11px;border-radius:12px;border:1px solid rgba(82,241,255,.12);background:rgba(3,18,28,.42)}.horizon small{display:block;color:#76969e;font-size:8px}.horizon strong{display:block;color:var(--cyan);font-size:12px;margin:5px 0}.horizon em{font-size:8px;color:var(--green);font-style:normal}.horizon.negative em{color:var(--red)}.market-chart{height:510px;padding:94px 20px 20px}.price-head{position:absolute;left:20px;right:20px;top:20px;z-index:3}.price-head .market-title{font-size:18px}.price-head .market-copy{max-width:320px}.chart-grid{inset:94px 20px 32px}.chart-badge{top:24px}
        .forecast-overlay{position:absolute;right:3%;bottom:15%;width:32%;height:42%;z-index:4;overflow:visible}.forecast-area{opacity:0;animation:forecastArea 8s ease-in-out infinite}.forecast-red,.forecast-green{fill:none;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke;stroke-dasharray:400;stroke-dashoffset:400}.forecast-red{stroke:#ff637d;animation:forecastDraw 8s ease-in-out infinite}.forecast-green{stroke:#36ee94;animation:forecastDraw 8s .9s ease-in-out infinite}.forecast-dot{fill:#071923;stroke-width:3;opacity:0;transform-box:fill-box;transform-origin:center;animation:forecastDot 8s ease-in-out infinite}.forecast-dot.red{stroke:#ff637d;animation-delay:.7s}.forecast-dot.green{stroke:#36ee94}.forecast-dot.d10{animation-delay:1.5s}.forecast-dot.d15{animation-delay:2.1s}.forecast-dot.d20{animation-delay:2.8s}.forecast-label{font-size:10px;font-weight:900;fill:#36ee94;opacity:0;animation:forecastLabel 8s ease-in-out infinite}.forecast-label.l5{fill:#ff637d;animation-delay:.7s}.forecast-label.l10{animation-delay:1.5s}.forecast-label.l15{animation-delay:2.1s}.forecast-label.l20{animation-delay:2.8s}@keyframes forecastDraw{0%,8%{stroke-dashoffset:400}45%,88%{stroke-dashoffset:0}100%{stroke-dashoffset:-400}}@keyframes forecastArea{0%,32%{opacity:0}46%,88%{opacity:.8}100%{opacity:0}}@keyframes forecastDot{0%,12%{opacity:0;transform:scale(.2)}22%,88%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.2)}}@keyframes forecastLabel{0%,15%{opacity:0;transform:translateY(4px)}25%,88%{opacity:1;transform:translateY(0)}100%{opacity:0}}
